contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount) public payable {
        // The contract only accepts play() with exactly TICKET_AMOUNT = 10 wei.
        // We take the amount as a parameter and ensure we can forward it.
        require(amount == 10, "amount must be the ticket price");
        require(address(this).balance >= amount, "not enough balance to send ticket price");

        uint potBefore = c.pot();
        uint cBalBefore = address(c).balance;

        (bool ok,) = address(c).call{value: amount}(abi.encodeWithSignature("play()"));
        // We do not require ok, because the rule must hold whether play reverts or succeeds.

        uint potAfter = c.pot();
        uint cBalAfter = address(c).balance;

        if (!ok || potBefore == 0) {
            // Either the call reverted (no state change) or there was no payout:
            // pot must have increased by exactly the ticket amount, and the contract
            // balance must have increased by the amount sent.
            assert(potAfter == potBefore + amount);
            assert(cBalAfter == cBalBefore + amount);
        } else {
            // A payout occurred: pot must be reset to zero and the contract balance
            // must have paid out (potBefore - FEE_AMOUNT) to the caller and FEE_AMOUNT to the bank.
            assert(potAfter == 0);
            assert(cBalAfter == cBalBefore + amount - potBefore);
        }
    }
}

