        require(amount == 10, "amount must equal ticket price");
        require(address(this).balance >= amount, "insufficient balance");

        uint potBefore = c.pot();
        uint contractBalanceBefore = address(c).balance;
        uint bankBefore = c.bank().balance;

        (bool success,) = address(c).call{value: amount}(abi.encodeWithSignature("play()"));

        uint potAfter = c.pot();
        uint contractBalanceAfter = address(c).balance;
        uint bankAfter = c.bank().balance;

        bool noPayout = (potBefore == 0);
        bool payoutOccurred = (potBefore > 0 && bankAfter == bankBefore + 1);

        assert(
            success
                ? (
                    noPayout
                        ? (potAfter == potBefore + amount && contractBalanceAfter == contractBalanceBefore + amount)
                        : (payoutOccurred && potAfter == 0)
                )
                : (potAfter == potBefore && contractBalanceAfter == contractBalanceBefore)
        );
    }
}

